//! 🧾️ Original terminal child work and retained IO refusals conserve actual physical backing.
use super::*;
use semio_framework_value::{native_decoding::NativeDecodeRetirementRecipient,retirement::admit_owned_retirement};
use std::cell::Cell;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant(f:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(f["grant"].clone()).unwrap()}
fn empty<T:RetireOwned>()->ControlledRetirement<Option<T>>{let mut slot=ControlledRetirement::new(None::<T>).ok().unwrap();assert!(slot.take_original().is_some());slot}
#[test]
fn original_receiving_terminal_child_quotes_actual_header_before_box_release(){
 let f=fixture();let caller=grant(&f);let mut accept=|_|true;let mut native=semio_framework_value::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut accept);
 let birth=semio_framework_value::retirement::owned_retirement_birth_bytes::<()>();native.charge(birth).unwrap();
 let (admitted,allocated,released)=crate::test_allocation::observe_backing(||admit_owned_retirement((),caller).ok().unwrap());let(mut child,receipt)=admitted;assert_eq!((allocated,released),(birth,0));assert_eq!(receipt.retained_capacity_bytes,birth);
 for _ in 0..f["maximumTurns"].as_u64().unwrap(){if child.terminal_is_empty(){break}native.checkpoint().unwrap();native.charge(child.next_capacity_byte_demand(caller.maximum_copy_bytes).unwrap()).unwrap();let(step,allocated,released)=crate::test_allocation::observe_backing(||child.close_step(caller).unwrap());assert_eq!((allocated,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 assert!(child.terminal_is_empty());let child_bytes=std::mem::size_of_val(child.as_ref());let pointer=child.as_ref()as*const dyn ErasedSnapshotRetirement as*const()as usize;
 let mut frame=NativeSnapshotReceiving::<(),()>{pending:std::mem::ManuallyDrop::new(Some(child)),intermediate:empty(),output:empty()};
 let observed_copy=frame.next_copy_byte_demand().unwrap();let copy=std::mem::size_of::<Option<Box<dyn ErasedSnapshotRetirement>>>();assert_eq!(copy,f["terminalChild"]["slotNativeWords"].as_u64().unwrap()as usize*std::mem::size_of::<usize>());assert_eq!(frame.next_capacity_byte_demand(copy).unwrap(),0);assert_eq!(frame.next_release_byte_demand().unwrap(),child_bytes);assert_eq!(frame.next_depth_demand().unwrap(),2);
 for axis in f["terminalChild"]["denials"].as_array().unwrap(){let mut denied=caller;match axis.as_str().unwrap(){"maximumItems"=>denied.maximum_items=0,"maximumCopyBytes"=>denied.maximum_copy_bytes=0,"maximumReleaseBytes"=>denied.maximum_release_bytes=0,"maximumDepth"=>denied.maximum_depth=1,_=>unreachable!()};let(result,allocated,released)=crate::test_allocation::observe_backing(||frame.close_step(denied));assert_eq!((allocated,released),(0,0));if let Ok(step)=result{assert_eq!(step.progress(),RetainedCloneProgress::default());}assert_eq!(frame.pending.as_ref().unwrap().as_ref()as*const dyn ErasedSnapshotRetirement as*const()as usize,pointer);}
 let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:child_bytes,maximum_depth:2};let(step,allocated,released)=crate::test_allocation::observe_backing(||frame.close_step(exact).unwrap());assert_eq!((allocated,released),(0,child_bytes));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:0,released_bytes:child_bytes});assert!(frame.terminal_is_empty());assert_eq!(observed_copy,copy,"original terminal child shell demand must quote the actual Option<Box<dyn>> move");println!("[DEBUG] Original receiving terminal child exactHeader=true zeroAllocation=true fourDenialsUnchanged=true realBoxRelease=true");
}
#[test]
fn original_receiving_canceled_publication_retains_exact_io_error_fields(){
 let f=fixture();let caller=grant(&f);let denied:RetainedCloneGrant=serde_json::from_value(f["deniedGrant"].clone()).unwrap();let cause=f["error"]["cause"].as_str().unwrap().to_owned();let code="fixture.original.error";assert_eq!(code,f["error"]["code"].as_str().unwrap());let message=f["error"]["message"].as_str().unwrap().to_owned();let mut diagnostics=Vec::with_capacity(1);diagnostics.push(semio_framework_diagnostic::Diagnostic::error(code,Default::default(),message));
 let error=semio_framework_io_schema::IoError{cause:ValueError::new(ValueRefusalKind::InvalidValue,cause),diagnostics};let backing=match &error.cause.message{std::borrow::Cow::Owned(text)=>text.capacity(),_=>0}+error.diagnostics.capacity()*std::mem::size_of::<semio_framework_diagnostic::Diagnostic>()+error.diagnostics[0].code.0.capacity()+error.diagnostics[0].message.capacity();assert_eq!(serde_json::to_value(error.cause.message.as_ref()).unwrap(),f["error"]["cause"]);assert_eq!(serde_json::to_value(&error.diagnostics[0].code.0).unwrap(),f["error"]["code"]);assert_eq!(serde_json::to_value(&error.diagnostics[0].message).unwrap(),f["error"]["message"]);
 let mut original=Some(Err(error));let live=Cell::new(true);let mut observe=|_|live.get();let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=semio_framework_value::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observe);native.install_retirement_recipient(&mut recipient).unwrap();native.charge(backing).unwrap();
 let addresses=|result:&semio_framework_io_schema::IoResult<String>|{let error=result.as_ref().err().unwrap();[error.cause.message.as_ptr()as usize,error.diagnostics.as_ptr()as usize,error.diagnostics[0].code.0.as_ptr()as usize,error.diagnostics[0].message.as_ptr()as usize]};let pointers=addresses(original.as_ref().unwrap());let mut unadmitted=super::super::NativeSnapshotDecodeOwner::new(&mut native,denied);let(result,allocated,released)=crate::test_allocation::observe_backing(||unadmitted.receive::<(),semio_framework_io_schema::IoResult<String>>(|_slot,_native,_body|Ok(original.take().unwrap())));assert_eq!((allocated,released),(0,0));assert_eq!(result.err().unwrap().kind,ValueRefusalKind::WorkLimit);assert_eq!(unadmitted.progress(),RetainedCloneProgress::default());drop(unadmitted);assert_eq!(addresses(original.as_ref().unwrap()),pointers);assert!(!native.has_retirement_owner());
 let mut owner=super::super::NativeSnapshotDecodeOwner::new(&mut native,caller);let(result,mut born,released)=crate::test_allocation::observe_backing(||owner.receive::<(),semio_framework_io_schema::IoResult<String>>(|_slot,_native,_body|{let output=original.take().unwrap();live.set(false);Ok(output)}));assert_eq!(released,0);assert!(original.is_none());let progress=owner.progress();assert_eq!(born,progress.retained_capacity_bytes);assert_eq!(result.err().unwrap().kind,ValueRefusalKind::Canceled);drop(owner);assert!(native.has_retirement_owner());
 live.set(true);let(result,allocated,released)=crate::test_allocation::observe_backing(||native.close_retirement_recipient(denied));assert_eq!((allocated,released),(0,0));if let Ok(step)=result{assert_eq!(step.progress(),RetainedCloneProgress::default());}assert!(native.has_retirement_owner());let mut total_released=0;
 for _ in 0..f["maximumTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(step,allocated,released)=crate::test_allocation::observe_backing(||native.close_retirement_recipient(caller).unwrap());let receipt=step.progress();assert_eq!((allocated,released),(receipt.retained_capacity_bytes,receipt.released_bytes));born+=allocated;total_released+=released;}
 assert!(!native.has_retirement_owner());assert_eq!(total_released,born+backing);drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original receiving IoResult error preadmissionPointersUnchanged=true canceledPublication=true originalBackingHeld=true zeroGrantUnchanged=true exactPhysicalConservation=true independentSerde=true");
}


#[test]
fn original_receiving_publication_header_denials_retain_exact_output_backing(){
 let f=fixture();let caller=grant(&f);let law=&f["publicationHeader"];let close:RetainedCloneGrant=serde_json::from_value(law["closeGrant"].clone()).unwrap();assert_eq!(law["closeAuthority"],"independentCallerWallet");let layout=law["layouts"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();let header=layout["headerBytes"].as_u64().unwrap()as usize;assert_eq!(header,std::mem::size_of::<Option<String>>());assert_eq!(std::mem::size_of::<Option<()>>(),law["intermediateBytes"].as_u64().unwrap()as usize);
 for entry in law["entries"].as_array().unwrap(){for axis in law["admissionDenials"].as_array().unwrap(){let mut original=Some(f["error"]["cause"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let backing=original.as_ref().unwrap().capacity();let mut denied=caller;match axis.as_str().unwrap(){"maximumItems"=>denied.maximum_items=0,"maximumCapacityBytes"=>denied.maximum_capacity_bytes=0,"maximumDepth"=>denied.maximum_depth=0,_=>unreachable!()};let mut observer=|_|true;let mut native=semio_framework_value::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observer);let mut owner=super::super::NativeSnapshotDecodeOwner::new(&mut native,denied);let mut cursor=Some(());let(result,born,released)=crate::test_allocation::observe_backing(||if entry=="receive"{owner.receive::<(),String>(|_,_,_|Ok(original.take().unwrap()))}else{owner.drive_cursor(&mut cursor,|_,_,_|(Ok(original.take()),Default::default()))});assert_eq!(result.unwrap_err().kind,match axis.as_str().unwrap(){"maximumItems"=>ValueRefusalKind::WorkLimit,"maximumCapacityBytes"=>ValueRefusalKind::OwnershipLimit,"maximumDepth"=>ValueRefusalKind::DepthLimit,_=>unreachable!()});assert_eq!((born,released,owner.progress()),(0,0,Default::default()));assert_eq!(original.as_ref().unwrap().as_ptr(),pointer);assert!(cursor.is_some());drop(owner);assert!(!native.has_retirement_owner());let mut source=ControlledRetirement::new(original.take().unwrap()).ok().unwrap();close_controlled(&mut source,close,backing);}}
 for entry in law["entries"].as_array().unwrap(){for case in law["cases"].as_array().unwrap(){
  let accepted=case=="exact";let declared=layout[format!("{}CopyBytes",case.as_str().unwrap())].as_u64().unwrap()as usize;let source_grant=RetainedCloneGrant{maximum_copy_bytes:declared,..caller};
  let mut original=Some(f["error"]["cause"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let backing=original.as_ref().unwrap().capacity();let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=semio_framework_value::NativeDecodeControl::new(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();native.charge(backing).unwrap();let mut owner=super::super::NativeSnapshotDecodeOwner::new(&mut native,source_grant);let mut cursor=Some(());
  let(result,born,released)=crate::test_allocation::observe_backing(||if entry=="receive"{owner.receive::<(),String>(|_,_,_|Ok(original.take().unwrap()))}else{owner.drive_cursor(&mut cursor,|_,_,_|(Ok(original.take()),Default::default()))});assert!(original.is_none());if entry=="cursor"{assert!(cursor.is_none());}let progress=owner.progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(progress.copied_bytes,if accepted{declared}else{law["intermediateBytes"].as_u64().unwrap()as usize});drop(owner);
  if accepted{let output=result.unwrap();assert_eq!(output.as_ptr(),pointer);assert_eq!(output.as_str(),f["error"]["cause"].as_str().unwrap());assert!(!native.has_retirement_owner());let mut destination=ControlledRetirement::new(output).ok().unwrap();close_controlled(&mut destination,close,backing);
  }else{let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(error.message,"snapshot publication exceeds original physical grant");assert!(native.has_retirement_owner());let mut receipt=RetainedCloneProgress::default();let mut total_released=released;let mut total_born=born;let(zero,allocated,released)=crate::test_allocation::observe_backing(||native.close_retirement_recipient(Default::default()).unwrap());assert_eq!((zero.progress(),allocated,released),(Default::default(),0,0));assert!(native.has_retirement_owner());for _ in 0..f["maximumTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let remaining=remaining(close,receipt);let(step,allocated,released)=crate::test_allocation::observe_backing(||native.close_retirement_recipient(remaining).unwrap());assert_eq!((allocated,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));total_born+=allocated;total_released+=released;receipt=receipt.checked_add(step.progress()).unwrap();}assert!(!native.has_retirement_owner());assert_eq!(total_released,total_born+backing);}
 }}
 for case in ["zero","oneShort"]{let original=f["error"]["cause"].as_str().unwrap().to_owned();let pointer=original.as_ptr();let backing=original.capacity();let mut frame=NativeSnapshotReceiving::<(),String>{pending:std::mem::ManuallyDrop::new(None),intermediate:empty(),output:ControlledRetirement::new(Some(original)).ok().unwrap()};let mut receipt=RetainedCloneProgress::default();let denied=RetainedCloneGrant{maximum_copy_bytes:layout[format!("{case}CopyBytes")].as_u64().unwrap()as usize-law["intermediateBytes"].as_u64().unwrap()as usize,..caller};let(result,born,released)=crate::test_allocation::observe_backing(||take_output(&mut frame,denied,&mut receipt,std::mem::size_of::<NativeSnapshotReceiving<(),String>>()));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!((born,released,receipt),(0,0,Default::default()));assert_eq!(frame.output.original().unwrap().as_ref().unwrap().as_ptr(),pointer);close_controlled(&mut frame.output,close,backing);assert!(frame.terminal_is_empty());}
 eprintln!("[DEBUG] Actual receive+cursor declared zero/one-short/exact header laws: denied original frame pointer inspected heap0, exact caller backing preserved, no source-slot claim after admission, funded cumulative physical close");
}
fn close_controlled<T:RetireOwned>(owner:&mut ControlledRetirement<T>,original:RetainedCloneGrant,backing:usize){let mut receipt=RetainedCloneProgress::default();for _ in 0..4096{if owner.terminal_is_empty(){break}let grant=remaining(original,receipt);let(step,allocated,released)=crate::test_allocation::observe_backing(||owner.step(grant).unwrap());assert_eq!((allocated,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));receipt=receipt.checked_add(step.progress()).unwrap();}assert!(owner.terminal_is_empty());assert_eq!(receipt.released_bytes,backing+receipt.retained_capacity_bytes);}
fn remaining(original:RetainedCloneGrant,receipt:RetainedCloneProgress)->RetainedCloneGrant{assert!(receipt.fits(original));RetainedCloneGrant{maximum_items:original.maximum_items-receipt.copied_items,maximum_copy_bytes:original.maximum_copy_bytes-receipt.copied_bytes,maximum_capacity_bytes:original.maximum_capacity_bytes-receipt.retained_capacity_bytes,maximum_release_bytes:original.maximum_release_bytes-receipt.released_bytes,..original}}
